export const contenusRegion: Record<RegionSlug, RegionContenu> = {
  paca,
  occitanie,
  "hauts-de-france": hautsDeFrance,
};

export function trouverContenu(slug: string): RegionContenu | undefined {
  return Object.hasOwn(contenusRegion, slug) ? contenusRegion[slug as RegionSlug] : undefined;
}

export type Suggestion = {
  type: "region" | "animal" | "association" | "habitat";
  libelle: string;
  detail: string;
  region: string;
  href?: string;
};

export const indexRecherche: Suggestion[] = [
  ...regionsCarte.map<Suggestion>((r) => ({
    type: "region",
    libelle: r.nom,
    detail: r.contenu ? "Région" : "Bientôt disponible",
    region: r.slug,
    href: r.contenu ? `/carte/${r.contenu}` : undefined,
  })),
  ...Object.values(contenusRegion).flatMap((c) => [
    ...c.animaux.map<Suggestion>((a) => ({
      type: "animal",
      libelle: a.nom,
      detail: c.nom,
      region: c.slug,
      href: `/carte/${c.slug}#animal-${a.slug}`,
    })),
    ...c.associations.map<Suggestion>((a) => ({
      type: "association",
      libelle: a.nom,
      detail: c.nom,
      region: c.slug,
      href: `/carte/${c.slug}#association-${a.slug}`,
    })),
    ...c.habitats.map<Suggestion>((h) => ({
      type: "habitat",
      libelle: `${h.titre} — ${h.sousTitre}`,
      detail: c.nom,
      region: c.slug,
      href: `/carte/${c.slug}#habitat-${h.slug}`,
    })),
  ]),
];
